design_text:
{
  "site_summary": "A shaded inner courtyard with very free-draining soil and low moisture, inhabited by one digging husky.",
  "layout_strategy": "The scheme stacks in three distinct height layers to outwit the digging husky: vertical hanging baskets at eye level for trailing succulents, mid-height heavy planters against the walls for upright architectural foliage and herbs, and a protected ground-level grazing tray secured against heavy paws.",
  "combination_logic": "The combination relies on contrasting architectural forms and textures, pairing the rigid, upright swords of Sansevieria with the soft rosettes of Echeveria and the woody, textured foliage of Sage and Oregano. Seasonal changes bring subtle shifts in leaf sheen and occasional tiny blooms, while evergreen textures ensure year-round structure in the shade.",
  "zones": [
    {
      "zone_name": "Railing Succulent Cascade",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "On high courtyard wall brackets, out of reach of the husky, receiving filtered partial shade and ambient light.",
      "plants": [
        {
          "scientific_name": "Echeveria elegans",
          "common_name": "Hens and Chickens",
          "why": "Adapts well to low moisture and partial shade while producing charming rosettes.",
          "role_in_combination": "Provides soft, rounded rosette textures that contrast sharply with the spiky vertical plants below."
        },
        {
          "scientific_name": "Crassula argentea",
          "common_name": "Jade Plant",
          "why": "Thrives in free-draining soil with minimal water requirements.",
          "role_in_combination": "Adds woody stems and fleshy, glossy leaves that catch the light high up on the wall."
        }
      ],
      "maintenance": [
        "Water thoroughly only when the soil is completely dry, roughly every two weeks in summer and monthly in winter.",
        "Fertilise with a low-nitrogen succulent feed once in mid-spring.",
        "Prune any leggy stems in early spring to encourage bushy growth."
      ]
    },
    {
      "zone_name": "Wall-Mounted Architectural Shield",
      "zone_role": "screening",
      "layer": "mid",
      "placement": "In heavy, wall-mounted masonry containers at waist height along the perimeter wall in partial shade.",
      "plants": [
        {
          "scientific_name": "Sansevieria trifasciata",
          "common_name": "Snake Plant",
          "why": "Extremely drought-tolerant and handles partial shade effortlessly.",
          "role_in_combination": "Contributes dramatic vertical height and rigid architectural lines that anchor the mid-layer."
        },
        {
          "scientific_name": "Salvia officinalis",
          "common_name": "Sage",
          "why": "Loves free-draining soil and partial shade conditions.",
          "role_in_combination": "Introduces grey-green, tactile foliage that softens the rigid geometry of the snake plant."
        }
      ],
      "maintenance": [
        "Check soil moisture weekly, watering sparingly as roots rot easily in damp conditions.",
        "Prune sage back by a third after flowering in summer to maintain a compact shape.",
        "Repot into slightly larger heavy containers every three years in spring."
      ]
    },
    {
      "zone_name": "Protected Husky Herb Patch",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "In a heavy, weighted ground-level timber trough secured with wire mesh, located in partial shade.",
      "plants": [
        {
          "scientific_name": "Origanum vulgare hirtum",
          "common_name": "Oregano",
          "why": "Tough low-growing herb that tolerates low moisture and partial shade.",
          "role_in_combination": "Provides a low, aromatic ground-hugging mat that can be safely nibbled by the dog."
        },
        {
          "scientific_name": "Alyssum spp.",
          "common_name": "Alyssum",
          "why": "Low moisture tolerant and creates a dense flowering ground cover.",
          "role_in_combination": "Adds delicate floral clusters and a sweet scent at ground level, softening the edges of the heavy planter."
        }
      ],
      "maintenance": [
        "Water lightly once a week during dry summer spells, keeping the wire mesh intact.",
        "Trim back alyssum and oregano slightly after their main flowering flush in mid-summer to promote fresh growth."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels across all containers, ensuring the free-draining mix dries out completely between waterings.",
      "frequency": "Every week",
      "season": "Summer"
    },
    {
      "task": "Prune back woody herbs like sage and clear away spent foliage from the hanging baskets.",
      "frequency": "Once at the beginning of the season",
      "season": "Spring"
    },
    {
      "task": "Relocate tender succulents and sensitive container plants to a frost-free, sheltered spot.",
      "frequency": "Once as temperatures drop",
      "season": "Winter"
    }
  ],
  "care_cautions": [
    "Overwatering the Sansevieria trifasciata and Crassula argentea in the shaded courtyard can quickly lead to root rot.",
    "The husky may attempt to dig into or overturn the ground-level planter if the wire mesh protection is not securely fastened.",
    "The low light levels in the partial shade courtyard may cause leggy growth in the Echeveria elegans if not positioned to catch maximum ambient light."
  ],
  "pet_safety_note": "All ground-level herbs are non-toxic and safely caged behind heavy wire mesh to satisfy the dog's curiosity without letting him destroy the root systems."
}
